-- 2. SANEAMENTO DE VÍNCULOS E UNIÕES INCORRETAS
-- =====================================================================
-- Perón: remove uniões espúrias de Mario Tomás Perón (o pai) com Eva Perón e Isabel Perón
DELETE FROM uniao_filhos WHERE uniao_id IN ('pub_u_pub_arv_peron_pub_peron_mario_tomas_peron_pub_peron_ev', 'pub_u_pub_arv_peron_pub_peron_mario_tomas_peron_pub_peron_is');
DELETE FROM arvore_membros WHERE uniao_id IN ('pub_u_pub_arv_peron_pub_peron_mario_tomas_peron_pub_peron_ev', 'pub_u_pub_arv_peron_pub_peron_mario_tomas_peron_pub_peron_is');
DELETE FROM unioes WHERE id IN ('pub_u_pub_arv_peron_pub_peron_mario_tomas_peron_pub_peron_ev', 'pub_u_pub_arv_peron_pub_peron_mario_tomas_peron_pub_peron_is');

-- Rockefeller: remove união absurda de John D. Rockefeller III com a avó Laura Spelman
DELETE FROM uniao_filhos WHERE uniao_id = 'pub_u_pub_arv_rockefeller_pub_rockefeller_john_d_rockefeller';
DELETE FROM arvore_membros WHERE uniao_id = 'pub_u_pub_arv_rockefeller_pub_rockefeller_john_d_rockefeller';
DELETE FROM unioes WHERE id = 'pub_u_pub_arv_rockefeller_pub_rockefeller_john_d_rockefeller';

-- Hitler: desvincula William Patrick Hitler de Alois Hitler Sr. e Klara Pölzl
DELETE FROM uniao_filhos WHERE pessoa_id = 'pub_hitler_william_patrick_hitler';
-- Remove placeholder anônimo do marido de Angela Hitler (será substituído por Leo Raubal)
DELETE FROM uniao_filhos WHERE uniao_id = 'pub_u_pub_arv_hitler_pub_ph_pub_hitler_angela_hitler_pub_hit';
DELETE FROM arvore_membros WHERE uniao_id = 'pub_u_pub_arv_hitler_pub_ph_pub_hitler_angela_hitler_pub_hit';
DELETE FROM unioes WHERE id = 'pub_u_pub_arv_hitler_pub_ph_pub_hitler_angela_hitler_pub_hit';
DELETE FROM arvore_membros WHERE pessoa_id = 'pub_ph_pub_hitler_angela_hitler';
DELETE FROM pessoas WHERE id = 'pub_ph_pub_hitler_angela_hitler';

-- Stalin: remove placeholder anônimo do marido de Svetlana (será substituído por William Wesley Peters)
DELETE FROM uniao_filhos WHERE uniao_id = 'pub_u_pub_arv_stalin_pub_ph_pub_stalin_svetlana_alliluyeva_p';
DELETE FROM arvore_membros WHERE uniao_id = 'pub_u_pub_arv_stalin_pub_ph_pub_stalin_svetlana_alliluyeva_p';
DELETE FROM unioes WHERE id = 'pub_u_pub_arv_stalin_pub_ph_pub_stalin_svetlana_alliluyeva_p';
DELETE FROM arvore_membros WHERE pessoa_id = 'pub_ph_pub_stalin_svetlana_alliluyeva';
DELETE FROM pessoas WHERE id = 'pub_ph_pub_stalin_svetlana_alliluyeva';

-- =====================================================================
-- 3. ATUALIZAÇÕES DE PESSOAS EXISTENTES (SEXO, MINIBIO, STATUS VIVO)
-- =====================================================================
UPDATE pessoas SET sexo = 'F' WHERE id = 'pub_hitler_klara_polzl';
UPDATE pessoas SET sexo = 'M' WHERE id IN ('pub_klabin_israel_klabin', 'pub_klabin_celso_lafer');
UPDATE pessoas SET is_vivo = 1 WHERE id IN ('pub_stalin_chrese_evans', 'pub_peron_isabel_peron', 'pub_rockefeller_john_d_rockefeller_iv', 'pub_klabin_israel_klabin', 'pub_klabin_celso_lafer', 'pub_klabin_horacio_lafer_piva');

